INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields, split) VALUES ('rm-159169196', 'rapidapi_uk_real_estate_rightmove', '159169196', 'https://www.rightmove.co.uk/properties/159169196', 1075000, NULL, 4, 4, 'detached', 'Brook Lane, Great Baddow, Chelmsford CM2', 'CM2 7SX', 51.701874, 0.49526, 'freehold', NULL, NULL, NULL, 'D', 'C', 'A', 'ground', '["Stylish traditional family home", "Countryside setting with open views", "Private gated access and parking", "Four bedrooms, three with en-suites", "Bespoke kitchen with lantern ceiling", "Underfloor heating", "Outbuilding with Golf Simulator", "Victorian style Botanic Glasshouse", "Sought-after location near Great Baddow", "Excellent road and rail links"]', 'Within the sought-after area of Great Baddow, this spacious 4 bedroom detached property offers stunning views over open countryside, three en-suite''s, private gated parking, good sized garden featuring a Victorian Botanic Glasshouse and an outbuilding featuring a golf simulator. The property is approached by a private gated entrance, passing and outbuilding to a sizeable parking area and the garden beyond. Step inside Mapletree Cottage, which is accessed either through the kitchen or from the front entrance porch. There is a central L-shaped sitting room/hall with feature brick fireplace incorporating a woodburning stove, also offering access to the bedrooms and further reception rooms. The main reception/sitting room is dual aspect with bi-folding doors, overlooking the garden , with an adjoining dining room. The bespoke fitted kitchen is flooded with natural light with a lantern roof, large central island/breakfast bar with wine fridge and ample fitted units incorporating appliances and a range cooker. There are double french doors leading out to the garden. The ground floor bathroom is off the dining/reception. Three of the bedrooms are on the ground floor, two featuring en-suite shower rooms - the third bedroom could be utilised as a study/home office. To the first floor is the stylish principal bedroom suite with walk-in wardrobe and en-suite shower room. The property features underfloor heating (electric), stylish tiled floors, feature lighting and some exposed timbers. There is also mains gas to the property.
INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields, split) VALUES ('rm-159931904', 'rapidapi_uk_real_estate_rightmove', '159931904', 'https://www.rightmove.co.uk/properties/159931904', 350000, 'offers_over', 2, 1, 'end_of_terrace', 'Violet Close, Cambridge, CB1', 'CB1 9YW', 52.185112, 0.182186, 'freehold', NULL, NULL, NULL, 'C', 'C', 'A', NULL, '["Two-Bedroom End Terrace Home", "Lounge/Diner", "Conservatory", "Loft Boarded for Storage", "Garage with Electricity Supply", "EPC Rating - C"]', 'Located in the popular, well-connected village of Cherry Hinton, this delightful two-bedroom end-terrace home offers a perfect blend of modern comfort and convenience. The spacious lounge/diner leads to a bright conservatory, adding extra living space. The fitted kitchen includes an electric oven and hob, ample storage, and space for appliances. Upstairs, you''ll find two well-proportioned bedrooms and a stylish family bathroom with a bath, overhead shower, WC, and basin. The loft offers valuable additional storage. The property benefits from gardens to the front, side, and rear, plus a garage and off-street parking on the driveway. Cherry Hinton is a vibrant village with excellent local amenities and easy access to Cambridge city centre.
INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields, split) VALUES ('rm-160404692', 'rapidapi_uk_real_estate_rightmove', '160404692', 'https://www.rightmove.co.uk/properties/160404692', 1000000, 'guide_price', 6, 3, 'terraced', 'High Street, Sevenoaks, Kent', 'TN13 1JG', 51.268787, 0.193784, 'freehold', NULL, NULL, NULL, NULL, 'C', 'B', 'ground', '["Town centre location", "Permit parking", "Could be divided into two separate dwellings", "A courtyard garden, great for al fresco dining", "Less than a mile from the mainline station", "Grade 2 listed"]', '44 High Street is an outstanding period house, set in an enviable position in the heart of Sevenoaks, just moments from the wide open spaces of Knole Park, yet moments from the town centre’s shops and amenities. The accommodation is arranged across four well-presented levels, and combines character features with elegant, modern fittings, with the layout lending itself to use as a large single house, or to be divided into two separate dwellings. On the ground floor, the entrance hall opens onto an inner hallway via wooden double doors, which lead to the comfortable sitting room with its cast-iron and tile-surrounded fireplace. The sitting room opens onto the rear garden, with a glass door welcoming plenty of natural light. Also on the ground floor there is a well-equipped kitchen with modern units, integrated appliances and space for a dining table.
INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields, split) VALUES ('rm-160604786', 'rapidapi_uk_real_estate_rightmove', '160604786', 'https://www.rightmove.co.uk/properties/160604786', 1200000, NULL, 2, 2, 'flat', 'Hand & Flower House, 617 Kings Road, SW6', 'SW6 2ES', 51.477657, -0.189473, 'share_of_freehold', 240, 3318.0, 200.0, 'F', 'C', 'A', 'first', '["High specification first floor apartment", "Open living, kitchen & dining", "Two bedrooms, two bathrooms", "Walking distance to amenities on the Kings Road"]', 'A larger than typical, two double bedroom lateral apartment, benefitting from a plethora of natural light and mod-cons such as air-conditioning throughout.
