INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields, split) VALUES ('rm-172499633', 'rightmove', '172499633', 'https://www.rightmove.co.uk/properties/172499633', 800000, NULL, 2, 2, 'flat', 'Eagle Point, City Road, London', 'EC1V 1AR', 51.527404, -0.0901, 'leasehold', 239, 7000, NULL, 'F', 'C', 'A', NULL, '["Landmark Eagle Point (The Eagle) development on City Road, EC1V", "24-hour concierge and on-site security/CCTV", "Residents’ leisure suite including gym and pool", "Thermal suite elements (sauna/steam-style facilities)", "Residents’ cinema/screening room", "Residents’ lounge/social spaces and landscaped outdoor areas", "Sainsbury’s Local on-site for day-to-day convenience", "Moments from Old Street (Tech City / Silicon Roundabout)", "Easy access to Shoreditch, Clerkenwell and the Barbican", "Strong wider connectivity via Moorgate / Liverpool Street (Elizabeth line)"]', 'Set within Eagle Point (also known as The Eagle) on City Road, EC1V, this apartment offers the rare combination of a prime Zone 1 address, strong on-site management and an “all-in-one” resident lifestyle on the City / Shoreditch fringe.
INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields, split) VALUES ('rm-172782107', 'rapidapi_uk_real_estate_rightmove', '172782107', 'https://www.rightmove.co.uk/properties/172782107', 1200000, NULL, 3, 2, 'terraced', 'Catherine Grove, Greenwich', 'SE10 8BS', 51.474606, -0.01843, 'freehold', NULL, NULL, NULL, 'E', 'C', 'C', NULL, '["Sought After Location", "No Work Required", "Period Family Home", "Three Double Bedrooms", "Two Bathrooms", "Home Office"]', 'A beautifully presented three double bedroom, two bathroom period family home which is situated in the Ashburnham Triangle conservation area. Further benefiting from a home office in the garden. This family home is over 1,300 sf ft. A viewing is highly recommended.
INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields, split) VALUES ('rm-173123300', 'rightmove', '173123300', 'https://www.rightmove.co.uk/properties/173123300', 1150000, 'guide_price', 5, 3, 'semi_detached', 'Cuckmans Drive, St. Albans, AL2', 'AL2 3AX', 51.730855, -0.361608, 'freehold', NULL, NULL, NULL, 'E', 'C', 'A', NULL, '["Five generous bedrooms", "Two en-suite shower rooms", "Arranged over three floors", "Stunning kitchen/family/dining area", "Separate reception room", "Laundry room", "Large private garden", "Beautifully presented throughout", "Driveway parking"]', 'Beautifully presented and thoughtfully designed, this substantial five-bedroom semi-detached home offers versatile living space perfectly suited to modern family life. Arranged over three floors, the property combines generous proportions with a practical layout, creating a home that is as functional as it is stylish.
INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields, split) VALUES ('rm-173172728', 'rightmove', '173172728', 'https://www.rightmove.co.uk/properties/173172728', 800000, 'offers_over', 3, 2, 'flat', 'Sussex Way, London, N7', 'N7 6RR', 51.561682, -0.118237, 'leasehold', NULL, NULL, NULL, NULL, 'C', 'A', 'ground', '[]', 'Situated on the well-connected Sussex Way in North London, this well-proportioned three-bedroom flat offers a practical layout, generous living space, and the added benefit of a private garden. Arranged across two levels and extending to approximately 800 sq ft (74.2 sq m) of internal space, the property provides an ideal opportunity for families, first-time buyers, or investors seeking a home in a vibrant and convenient location. Upper Holloway Overground Station is just a short walk away, while Finsbury Park Station – offering Piccadilly and Victoria line services – is also within easy reach, making commuting into Central London fast and convenient. Several major bus routes stop just moments from your door, linking you directly to London Bridge, Waterloo, Trafalgar Square and more.
INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields, split) VALUES ('rm-173220800', 'rapidapi_uk_real_estate_rightmove', '173220800', 'https://www.rightmove.co.uk/properties/173220800', 1195000, NULL, 3, 2, 'detached', 'Sweet Hill, Brighton, BN1', 'BN1 8ZG', 50.87101, -0.163047, 'freehold', NULL, NULL, NULL, 'F', 'D', 'C', NULL, '["Beautifully presented 2-3 bedroom bungalow set on 2-acres with stables (originally laid out as three bedrooms)", "Renovated throughout with a versatile layout", "External fields currently set up for keeping horses on site", "Potential to extend the house and convert outbuildings", "Nestled on the South Downs National Park", "Spa pool and wrap around gardens with several fruit trees", "Energy efficiency through solar panels with a battery storage system, an air source heat pump and underfloor heating throughout. An EV smart charging point is installed by the garage.", "Excellent transport links by road to London, Gatwick and along the South Coast", "Excellent schools nearby", "Easy access by car or bus to the coast and Brighton & Hove City Centre"]', 'Introduction:
INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields, split) VALUES ('rm-173457845', 'rapidapi_uk_real_estate_rightmove', '173457845', 'https://www.rightmove.co.uk/properties/173457845', 1195000, 'guide_price', 4, 3, 'detached', 'Blasford Hill, Little Waltham, CM3', 'CM3 3PF', 51.778885, 0.473411, 'freehold', NULL, NULL, NULL, 'G', 'C', 'B', NULL, '["A generous four-bedroom detached country residence with original character and modern comfort.", "Set within expansive 3.5 acres of ground, including gardens, paddocks and woodland.", "Includes a self-contained annex, ideal as a home office, guest house or for extended family.", "Generously proportioned ground floor living spaces with formal reception, study, and airy conservatory.", "Stylish and practical kitchen/dining area with utility room and ground floor bathroom.", "First floor features four bedrooms, including two spacious principal rooms, with en-suite and shower room.", "Range of stables and outbuildings suitable for equestrian use, storage, or lifestyle needs.", "Located on Blasford Hill in the picturesque village of Little Waltham, Chelmsford, Essex.", "Excellent local amenities, schools, and strong community spirit; close to Chelmsford city centre.", "Strong transport links: regular buses, nearby rail stations, and easy access to A130/A120 for commuting."]', 'Set within expansive, beautifully maintained grounds, this four-bedroom detached Grade 11 residence presents a rare opportunity to acquire a country home that effortlessly blends contemporary comfort with original character. The property also benefits from a self-contained annex and a range of stables, offering exceptional versatility for a variety of lifestyles. The ground floor is thoughtfully arranged, with a welcoming entrance hall leading to generously proportioned living spaces. The impressive living room flows seamlessly into a bright and airy conservatory, creating the perfect environment for both family life and entertaining. A formal reception room offers an additional space for relaxation or social gatherings, while a charming study provides an ideal home-working environment. At the heart of the home, the kitchen/dining area combines style and practicality, complemented by a utility room and a well-appointed ground floor bathroom. The first floor accommodates four comfortable bedrooms, including two spacious principal rooms. A contemporary shower room and a private en-suite complete the sleeping quarters, offering convenience and privacy for family living. The self-contained annex provides flexible accommodation, ideal for extended family, guests, or independent living. It comprises a welcoming living/dining area, a kitchen, a shower room, and an additional bedroom, delivering both comfort and versatility. A range of stables and outbuildings enhance the property, providing practical facilities for equestrian use, storage, or other lifestyle pursuits. Combining space, charm, and modern comforts, this distinguished country residence offers an exceptional opportunity to enjoy flexible living within private, generous grounds. With its annex, extensive outbuildings, and beautifully balanced interior, the property embodies both character and contemporary appeal.', 'Beresfords, Country and Village', '2026-03-19T09:10:27Z', '2026-10-24T10:15:02Z', '[]', 'train');
INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields, split) VALUES ('rm-173567597', 'rapidapi_uk_real_estate_rightmove', '173567597', 'https://www.rightmove.co.uk/properties/173567597', 1000000, 'guide_price', 6, 3, 'detached', 'Tabors Avenue, Chelmsford, CM2', 'CM2 7ES', 51.720192, 0.499806, 'freehold', NULL, NULL, NULL, 'E', 'B', 'A', NULL, '["Substantially extended and upgraded detached residence over three spacious floors.", "Stylish, modern interiors ideal for contemporary family living.", "Ground floor features a spectacular open-plan lounge and dining area.", "Modern kitchen with generous workspace, pantry, and utility room.", "Dedicated office and convenient ground floor WC; air conditioning throughout.", "Principal suite with walk-in wardrobe, en-suite, plus additional bedrooms including one with balcony.", "Second floor offers two further bedrooms, bathroom, and flexible spaces for offices, studios, or hobbies.", "Substantial outbuilding with fully plumbed beauty room, kitchen, WC, and flexible space for annexe, gym, or studio.", "Excellent transport links: buses to Chelmsford city centre, Chelmsford mainline station, and upcoming Beaulieu Park station; easy road access via A12.", "Family-friendly location in CM2, Great Baddow East, with quality schools, green spaces, and proximity to shops, eateries, and leisure facilities."]', '** Guide Range £1,000,000 - £1,150,000 ** This exceptional detached residence has been significantly extended and upgraded in recent years, creating an impressive and beautifully designed home arranged over three spacious floors. Offering versatile accommodation and stylish modern interiors, the property is perfectly suited to contemporary family living. Upon entering, a welcoming entrance hall leads to the main living areas. The standout feature of the ground floor is the spectacular open-plan lounge and dining area, an expansive and light-filled space ideal for both relaxed family life and entertaining on a grand scale. The modern kitchen sits to the rear of the property and is thoughtfully designed with generous workspace and storage, complemented by a separate pantry and a practical utility room. A dedicated office provides the perfect work-from-home environment, while a convenient ground floor WC adds further practicality. Air conditioning has been installed to enhance comfort throughout the home. The integral garage is accessed internally and presents excellent potential for further extension or conversion into additional living accommodation, subject to the necessary permissions. The first floor offers four well-proportioned bedrooms arranged around a central landing. The impressive principal suite creates a luxurious retreat, complete with a walk-in wardrobe and private en-suite bathroom. One of the additional bedrooms benefits from access to a balcony, offering an elevated space to relax and enjoy the outlook. A stylish family bathroom serves the remaining bedrooms, while additional storage space ensures the home remains highly practical. The second floor continues the generous accommodation with two further bedrooms, ideal for growing families, visiting guests, or flexible uses such as additional offices, studios, or hobby rooms. This level also includes a bathroom and further storage areas. Adding even more versatility, the property benefits from a substantial outbuilding that includes a separate beauty room which is fully plumbed and offers exciting potential to be converted into a self-contained annexe. The outbuilding also incorporates additional flexible space along with a kitchen and WC, making it ideal for a studio, workspace, gym, guest suite, or entertainment area. Combining extensive modern upgrades, generous living space, and outstanding flexibility, this remarkable home offers an exceptional opportunity to enjoy stylish, contemporary living in a property designed to adapt to a wide range of lifestyles.', 'Beresfords, Country and Village', '2026-03-23T14:14:39Z', '2026-10-24T10:16:32Z', '[]', 'eval');
INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields, split) VALUES ('rm-173646677', 'rapidapi_uk_real_estate_rightmove', '173646677', 'https://www.rightmove.co.uk/properties/173646677', 1200000, NULL, 5, 3, 'semi_detached', 'Howard Road, New Malden', 'KT3 4DP', 51.402134, -0.254892, 'freehold', NULL, NULL, NULL, 'E', 'D', 'C', 'first', '["Sought After Location", "Newly Refurbished", "5 Bed Semi with Annex with en suite", "Premium finish throughout", "Stunning Kitchen Living Area", "Close to New Malden High Street", "Excellent Local Schools", "Courtyard Style Garden", "No Chain", "Vacant"]', 'Seou Esatate Agents are please to introduce this brand newly renovated property, prime located, situated just behind New Malden High Street, this property has been finished to an exceptional standard through out. Thoughtfully designed family home, ready to move in with no chain.
INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields, split) VALUES ('rm-173678513', 'rapidapi_uk_real_estate_rightmove', '173678513', 'https://www.rightmove.co.uk/properties/173678513', 1200000, NULL, 5, 2, 'semi_detached', 'Howard Road, New Malden, KT3', 'KT3 4DP', 51.40208, -0.25501, 'freehold', NULL, NULL, NULL, 'E', 'C', 'A', NULL, '["Fully renovated to high specification throughout", "Modern open plan kitchen with breakfast island", "3 floors of bright and spacious accommodation", "Sunny rear garden with store, study room and utility room", "Annex/gym/office with ensuite shower", "3 bathrooms with Japanese toilets and guest cloakroom", "Driveway parking and side access to garden", "Moments from New Malden High Street and Train Station"]', 'Finished to an incredible standard throughout, this stunning 5 bedroom family home offers modern interiors over 3-spacious floors, as well as an ensuite annex, ample storage space, and off-street parking.
INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields, split) VALUES ('rm-173691080', 'rightmove', '173691080', 'https://www.rightmove.co.uk/properties/173691080', 550000, 'offers_over', 1, 1, 'flat', 'Almeida Street, Islington, N1', 'N1 1TB', 51.539663, -0.104193, 'share_of_freehold', 982, 700, NULL, 'E', 'D', 'B', NULL, '["1 double bedroom garden flat", "Sole use of private garden", "Barnsbury Conservation area", "Own private entrance", "Superb access to both Angel and Highbury & Islington stations"]', 'A stunning 1 double bedroom garden flat set within this phenomenally central location, right in the heart of Islington, within the Barnsbury conservation area, moments form the vibrant amenities of Upper Street, yet retaining peace and tranquillity on this cul-de-sac section of the road. The property is accessed via its own private entrance , opening in to the beautiful, spacious reception room with the focal point of the room being a stunning decorative fireplace. The kitchen is modern, well-appointed and finished to a high specification. The shower room is beautifully designed with a stunning walk-in shower, WC, hand basin and a window. To the rear is a beautiful private tiered patio garden, backing on to the gardens of the houses on Napier Grove. Almeida Street is a no through road off Upper Street, home to the renowned Almeida Theatre. The property affords superb access to the transport at Angel Underground (Northern Line) and Highbury & Islington Station (National Rail & Victoria Line) providing excellent links around London. The buzz of Upper Street is only a short walk away. The celebrated gastropubs the The Pig & Butcher, the Albion and the Drapers Arms can be found locally within Barnsbury. Supermarkets Waitrose and Sainsbury''s are located at the Southern end of Liverpool Road, close to Angel.
