INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields, split) VALUES ('rm-174816428', 'rapidapi_uk_real_estate_rightmove', '174816428', 'https://www.rightmove.co.uk/properties/174816428', 450000, 'guide_price', 2, 1, 'flat', 'Springfield Road, Kingston Upon Thames', 'KT1 2SA', 51.40388, -0.301348, 'share_of_freehold', 900, NULL, NULL, 'C', 'C', 'B', NULL, '[]', 'An excellent two-bedroom garden floor apartment with direct access to a communal garden and parking. Set in a grand Victorian house. Located on a lovely residential road within walking distance of Kingston town centre and railway station, the Thames and Surbiton mainline station. The many benefits include a spacious living room with sitting and dining space, a bay window and a feature fireplace. There is a separate modern shaker-style kitchen with integral appliances and oak surfaces. The large master bedroom includes fitted wardrobes, plus a good-sized second bedroom. A contemporary white and stone shower room and a separate wc. Gas central heating and double glazing. There is an enclosed communal garden to the rear and parking. Council tax band C. Sold with a Share of the Freehold and a lease in excess of 900 years. We are informed the service charge is £90 per month. A lovely home with no onward chain.', 'Matthew James, Surbiton', '2026-04-23T09:06:50Z', '2026-10-24T10:54:14Z', '[]', 'eval');
