INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields, split) VALUES ('rm-87594642', 'rapidapi_uk_real_estate_rightmove', '87594642', 'https://www.rightmove.co.uk/properties/87594642', 1130000, 'guide_price', 5, 1, 'bungalow', 'Horseshoe Lane West, Merrow, GU1', 'GU1 2SZ', 51.245396, -0.543387, 'freehold', NULL, NULL, NULL, 'G', 'C', 'B', 'ground', '["5 bedrooms", "Approx. 2,127 sq ft of internal accommodation", "Flexible layout", "Large sitting room", "Kitchen with adjoining utility room", "Conservatory overlooking the garden", "Ample off-street parking", "Garage", "Mature, established rear garden", "Catchment for several schools"]', '"This is a substantial and flexible property, set back from the road behind a carriage driveway and enjoying a mature rear garden that gives a real sense of privacy. The layout works well for a number of buyer profiles, with generous ground floor living areas and the flexibility to use rooms in different ways as needs change. Upstairs, the first floor offers additional bedrooms and storage, making good use of the roof space without compromising comfort. Its proximity to several popular schools will be a key draw for many buyers, while the driveway, garage and garden all add to the practical appeal of the house." James Boyden - Chantries & Pewleys
INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields, split) VALUES ('rm-87710814', 'rightmove', '87710814', 'https://www.rightmove.co.uk/properties/87710814', 800000, NULL, 3, 2, 'flat', 'Leswin Road, Stoke Newington, London, N16', 'N16 7NX', 51.55993, -0.07326, 'leasehold', 115, 2589, 900, 'E', 'B', 'A', '1st', '["Gorgeous 3 bedroom flat on the 1st floor", "Located in a converted school house", "Bright reception room with ample space to relax", "Modern kitchen with dining space and fitted appliances", "3 sizeable bedrooms with floods of natural light", "Sleek shower room and additional en suite bathroom in the main bedroom", "Lovely terrace", "Located in the heart of Stoke Newington for amenities and transport links"]', 'Situated on the first floor of this attractive converted school, this stunning 3 bedroom flat boasts bright interiors and spacious rooms. It further benefits from a lovely private terrace.
INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields, split) VALUES ('rm-87720795', 'rapidapi_uk_real_estate_rightmove', '87720795', 'https://www.rightmove.co.uk/properties/87720795', 1150000, 'offers_over', 5, 2, 'detached', 'Winchelsey Rise, South Croydon', 'CR2 7BN', 51.35725, -0.083182, 'freehold', NULL, NULL, NULL, 'G', 'C', 'B', NULL, '["Stunning Five Bedroom Detached Family Home", "Sought After South Croydon Location", "Expansive Accommodation with Elegant Interiors", "Three Wonderful Reception Rooms", "Large Conservatory with Garden Views", "Well Equipped Kitchen and Utility", "Two Bath/Shower Rooms (One En-Suite) plus Guest WC", "Glorious Garden", "Garage and Generous Off Street Parking", "Close to Transport Links, Schools and Amenities"]', 'Marriott Vernon present this stunning five bedroom detached family home with off street parking, garage and glorious garden superbly situated in a sought after residential location in South Croydon, moments from Croham Hurst Woods. The property has been beautifully maintained and appointed by the current owners, offering expansive accommodation with elegant interiors and high quality finish throughout, as well as further scope to extend as desired, STPP. Features include three inviting reception rooms, well equipped kitchen and separate utility, two bath/shower rooms (one en-suite), gas central heating, double glazing, quality floor coverings and ample inbuilt storage.
