INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields, split) VALUES ('rm-89171175', 'rapidapi_uk_real_estate_rightmove', '89171175', 'https://www.rightmove.co.uk/properties/89171175', 1150000, 'guide_price', 5, 2, 'detached', 'Arkwright Road, South Croydon, Surrey', 'CR2 0LL', 51.34573, -0.07835, 'freehold', NULL, NULL, NULL, 'G', 'B', 'A', NULL, '["Large detached family house with double garage & driveway for several cars", "Walking distance to Sanderstead station and the village shops, cafes and restaurants", "Croham Hurst Woods just around the corner, ideal for afternoon strolls or dog walking", "Great location for schools, including The Ridgeway, Gresham, Croydon High School & Coombe Wood School", "Level rear garden with patio"]', 'Large detached family house with double garage and driveway for many cars. Ideally located for Sanderstead Village with shops, cafes and restaurants. Also walking distance to Sanderstead station and several bus routes. The home itself has a large welcoming hallway with convenient cloakroom. Tradional layout of separate kitchen, dining room and lounge with a study and conservatory overlooking the beautiful rear garden and patio area. Upstairs all the bedroom are doubles, the main bedroom with an en-suite bathroom and dressing area. Ideal home for the larger/extended family. Excellent local schools for all ages and lots of green open space, ideal for dog walking or afternoon stroll.
