INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields, split) VALUES ('rm-89990046', 'rightmove', '89990046', 'https://www.rightmove.co.uk/properties/89990046', 410000, 'guide_price', 2, 2, 'flat', 'Campbell Court, Nascot Wood, Watford WD17 4BU', 'WD17 4BU', 51.669735, -0.408568, 'leasehold', 109, 1500.0, 300.0, NULL, 'C', 'B', 'first', '["Chain free sale", "Surprisingly large and sunny aspect balcony", "Security entryphone", "Communal lift", "Lease term: 109 years remaining", "Service charge: £1500 per annum", "Ground rent: £300 per annum"]', 'This first-floor apartment offers bright and spacious accommodation throughout and is within walking distance of Watford Junction, the town centre and the beautiful Cassiobury Park. In addition, major road links A41, M1 and M25 can all be easily reached within just a few minutes'' drive. A children''s playground and green space along with a Tesco Express also feature within this highly sought after residential setting.
INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields, split) VALUES ('rm-89997285', 'rapidapi_uk_real_estate_rightmove', '89997285', 'https://www.rightmove.co.uk/properties/89997285', 1200000, 'offers_over', 4, 2, 'house', 'Greenham Road, London, N10', 'N10 1LN', 51.59786, -0.149592, 'freehold', NULL, NULL, NULL, 'E', 'B', 'A', NULL, '["4 bedrooms", "2 bathrooms", "utility room", "loft extension"]', 'A mid terraced house built in the late 1920''s on the sought after and desirable Greenham Road. A popular residential road with both professionals and families as close to the outstanding local schools and frequent bus routes. The house has a front garden and porch. The main door has original stained glass and leads to main hall. The reception rooms have been fully open, the chimney breasts have been removed which has created a wide and spacious room, ideal for large families or entertaining. There is a rear extension that covers the full width of the house. The kitchen is located on one side of the new extension and leads onto the utility room, that was the original kitchen prior to the work. The rear extension, opens onto the private patio, ideal for Al-fresco dining. The first floor has two large double bedrooms with generous built in wardobes. The third bedroom is a large study. The family bathroom features a corner bath. The top floor has the principal bedroom that has a Juliet balcony. There is a large shower room that is accessed from the hall. This great family house would suit families and professionals as close to both outstanding primary school and secondary schools.
INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields, split) VALUES ('rm-89999721', 'rightmove', '89999721', 'https://www.rightmove.co.uk/properties/89999721', 315000, NULL, 1, 1, 'flat', 'Basing Court, Peckham, London, SE15', 'SE15 5BF', 51.473316, -0.07269, 'leasehold', 120, 1944.5, 250, 'C', 'B', 'A', 'first', '["First Floor Flat", "One bedroom", "Communal bike storage & patio", "Secure entrance", "Total area: 485sqft", "Close to local amenities", "0.4mi to Peckham Rye station"]', 'Situated within a well-maintained residential development in the heart of Peckham, this bright and well-proportioned one-bedroom first-floor flat offers an excellent opportunity for first-time buyers, investors, or those seeking a convenient London base.
INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields, split) VALUES ('rm-90008523', 'rapidapi_uk_real_estate_rightmove', '90008523', 'https://www.rightmove.co.uk/properties/90008523', 500000, NULL, 2, 1, 'terraced', 'Haycroft Road, Surbiton, KT6', 'KT6 5AU', 51.37583, -0.304722, 'freehold', NULL, NULL, NULL, 'D', 'D', 'C', NULL, '["Two bedroom terraced house", "Stunning south facing garden", "Finished to a high standard throughout", "Within easy reach of excellent transport links", "Easy access to the A3", "Close to local amenities"]', 'This beautifully presented two bedroom terraced house offers contemporary living in a sought-after location. Finished to a high standard throughout, the property features a spacious living area, a modern fitted kitchen, a separate front reception room and two well-proportioned bedrooms. The interiors are thoughtfully designed with quality fixtures and fittings, creating a welcoming and comfortable home environment. The property is ideally situated within easy reach of excellent transport links and provides straightforward access to the A3, making it perfect for commuters. Local amenities, including shops, cafes, and schools, are just a short walk away, ensuring convenience for day-to-day living.
