INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields, split) VALUES ('rm-90476601', 'rapidapi_uk_real_estate_rightmove', '90476601', 'https://www.rightmove.co.uk/properties/90476601', 315000, NULL, 3, 1, 'house', 'Holton Hill, Brighton', 'BN2 6RQ', 50.83053, -0.067546, 'freehold', NULL, NULL, NULL, 'C', 'D', 'B', NULL, '["THREE BEDROOM END OF TERRACE HOUSE", "NO ONWARD CHAIN", "STUNNING VIEWS", "SOUTH WOODINGDEAN", "IDEAL FIRST TIME BUY OR FAMILY HOME"]', 'Robert Luff & Co are delighted to bring to market this spacious three bedroom, end of terrace house in the heart of Woodingdean. Holton Hill is located in South Woodingdean near the ever popular Happy Valley, with stunning views over The South Downs. Bus services can be found nearby in The Ridgway and Crescent Drive South for access into Brighton City Centre or the village of Rottingdean, good road links via the Falmer Road to the A27 and Falmer Railway Station. Local shops are in Cowley Drive and Warren Road/Warren Way. Local schools are available from nursery age to High School. For leisure time there are parks in Rudyard Road and Happy Valley. Plenty of walking or cycling routes are also available over the Downs.
