INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields, split) VALUES ('rm-91149165', 'rightmove', '91149165', 'https://www.rightmove.co.uk/properties/91149165', 475000, NULL, 4, 1, 'detached', 'Stuart Close, Emmer Green, Reading', 'RG4 8RF', 51.480564, -0.969743, 'freehold', NULL, NULL, NULL, 'E', 'D', 'B', NULL, '["Four bedroom detached family home", "Large living/dining room, fitted kitchen, study/t.v room", "Secluded south east facing rear garden", "Garage and parking", "No onward chain", "Requires some updating"]', 'A four bedroom detached family home requiring some updating, peacefully located in a quite cul-de-sac, just a short distance from both Emmer Green Primary and Highdown Secondary Schools, local shops & bus stops. With large living room, separate study/t.v room and fitted kitchen, enclosed south-east facing garden, garage and parking. No onward chain
INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields, split) VALUES ('rm-91214886', 'rapidapi_uk_real_estate_rightmove', '91214886', 'https://www.rightmove.co.uk/properties/91214886', 700000, NULL, 5, 3, 'house', 'The Tythings, Howe Green, Chelmsford, Essex, CM2', 'CM2 7TU', 51.709118, 0.519275, 'freehold', NULL, NULL, NULL, 'E', 'B', 'A', NULL, '["Substantial five bedroom family home", "No onward Chain", "Three reception rooms", "Garage and off road parking", "Two en-suites and family bathroom", "Highly requested village of Howe Green"]', 'Offered with no onward chain is this impressive five- bedroom family home ideally located in this highly sought-after village of Howe Green. Well-proportioned throughout this spacious home offers great contemporary and versatile living accommodation. To the ground floor the property consists of a welcoming entrance hallway which gives access to study with bay window, w/c and lounge which leads into the conservatory offering access to the rear garden. The ground floor accommodation continues and benefits from access to the dining room, utility room and the high specification kitchen which is ideal for family living and a great entertaining space. Access to the rear garden is via the kitchen patio doors which provides a seamless connection between indoor and outdoor spaces. The kitchen also offers independent access to the separate stairway which leads to the fifth bedroom / gym. The first floor provides four substantial size bedrooms with bedroom one and two both offering ensuite facilities. A further family bathroom is also located to the first floor. Externally, the property boasts a well-maintained rear garden, being mainly laid to lawn with a patio seating area. The property has a driveway providing off road parking and garage. Further benefits to this family home include double glazing and ample storage throughout. To appreciate this family home to its full potential, we strongly recommend an early internal inspection.
