INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields, split) VALUES ('rm-91769601', 'rapidapi_uk_real_estate_rightmove', '91769601', 'https://www.rightmove.co.uk/properties/91769601', 450000, 'guide_price', 2, 2, 'terraced', 'Great Eastern Street, Cambridge', 'CB1 3AD', 52.199364, 0.142868, 'freehold', NULL, NULL, NULL, 'C', 'D', 'B', NULL, '["Victorian terrace property", "Two bedrooms", "En-suite to main bedroom", "Recently fitted kitchen, bathroom and en-suite", "Immaculately presented", "Highly sought after location", "13 minute walk to Cambridge train station", "No onward chain", "Early viewing highly advised"]', 'Radcliffe & Rust Estate Agents are delighted to offer for sale this two-bedroom Victorian terrace property situated on Great Eastern Street in Cambridge, CB1. Occupying an enviable position just moments from the vibrant Mill Road district, this sought-after location offers the perfect blend of city living, excellent connectivity and a thriving local community. Renowned for its eclectic mix of independent cafés, restaurants, pubs, delicatessens and boutique shops, Mill Road is one of Cambridge''s most popular destinations, providing an abundance of amenities all within easy walking distance. Cambridge city centre, the historic market square and the Grafton Shopping Centre are all easily accessible, while nearby Parker''s Piece and Christ''s Pieces offer attractive open green spaces for recreation and leisure. Cambridge railway station is approximately a 10-minute walk away, providing direct services to London King''s Cross and Liverpool Street, making this an ideal location for commuters. The area is also well served by regular bus routes and excellent cycle links, with Addenbrooke''s Hospital, Cambridge Biomedical Campus and several of the city''s leading schools and colleges all within easy reach. Combining convenience, character and a vibrant community atmosphere, Great Eastern Street is a highly desirable location from which to enjoy everything Cambridge has to offer.
