INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields, split) VALUES ('rm-93106827', 'rapidapi_uk_real_estate_rightmove', '93106827', 'https://www.rightmove.co.uk/properties/93106827', 1150000, 'offers_over', 4, 3, 'end_of_terrace', 'Gildenhowe, Cambridge', 'CB3 1AY', 52.222385, 0.087564, 'freehold', NULL, NULL, NULL, 'F', 'B', 'A', NULL, '["Offered with no onward chain", "Secure parking and triple glazing", "Underfloor heating and heat recovery system", "Contemporary kitchen area with range of quality appliances", "University of Cambridge Primary School", "Close to supermarket and shopping and park and Ride", "Solar PV panels", "Central heating throughout and 24-hour rubbish disposal"]', 'Eddington is a newly developed neighbourhood on the western side of Cambridge and has all the benefits of being within 3 miles of the centre of the city, easily accessible by road, bus, bicycle (via dedicated cycle routes). Junction 13 off the M11 is just up from the Madingley Park and Ride, providing access to the south of the city and Addenbrooke''s biomedical campus. Eddington benefits from a wide range of amenities, including University of Cambridge Primary School, Bright Horizons nursery, market square, Sainsburys, Hyatt Centric hotel (open to the public and has bars, restaurants and a roof top terrace) and an excellent selection of independent restaurants, cafes and venues (Storey Field Centre). There are country walks at Brooks Leys along with landscaped grounds and children''s play areas.
