INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields, split) VALUES ('rm-93179394', 'rightmove', '93179394', 'https://www.rightmove.co.uk/properties/93179394', 550000, NULL, 2, 1, 'flat', 'Bruges Place, Camden', 'NW1 0TJ', 51.541301, -0.136875, 'leasehold', NULL, NULL, NULL, 'D', 'C', 'A', NULL, '["Two bedrooms", "Large terrace", "Balcony", "Gated development", "Gated parking", "Close to transport"]', 'A two bedroom split-level maisonette that comes with a large private terrace off the reception room, a second balcony which is accessible from the bedroom, a family bathroom, a fitted kitchen, off-street parking and a long lease of 179 years.
INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields, split) VALUES ('rm-93183936', 'rapidapi_uk_real_estate_rightmove', '93183936', 'https://www.rightmove.co.uk/properties/93183936', 450000, 'guide_price', 1, 1, 'flat', 'Oak Hill Road, Surbiton, KT6', 'KT6 6FB', 51.39021, -0.300549, 'leasehold', 244, 1800.0, 1.0, 'D', 'C', 'A', NULL, '["Luxury Apartment Within Modern Victorian Style Building Built Circa 2021", "Oak Hill Conservation Area", "0.2 miles from Surbiton Mainline Station (Waterloo approx. 17 mins)", "Open-Plan Kitchen and Reception Room with Private Terrace", "Access to Communal Gardens", "Double Bedroom with Built-In Wardrobe", "Neighbouring Nature Reserve", "Modern Bathroom", "Step-Free Access from Street"]', 'Seymours of Surbiton are delighted to offer this luxury apartment set within an imposing Victorian style building, sympathetically constructed in 2021. Located in the sought-after Oak Hill Conservation Area, just 0.2 miles from Surbiton Mainline Station, the apartment combines period character with contemporary design, high ceilings, and excellent natural light. The open-plan kitchen and reception room opens onto a private terrace and the bedroom benefits from built-in wardrobes. The property is within easy access to Surbiton’s shops, cafés, and restaurants, with central London reachable in approximately 17 minutes.', 'Seymours Estate Agents, Surbiton', '2026-09-15T17:50:15Z', '2026-10-24T10:54:08Z', '[]', 'train');
INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields, split) VALUES ('rm-93184068', 'rightmove', '93184068', 'https://www.rightmove.co.uk/properties/93184068', 1125000, NULL, 5, 4, 'terraced', 'Queenswood Road, Forest Hill, SE23', 'SE23 2QR', 51.432263, -0.043388, 'freehold', NULL, NULL, NULL, 'F', 'D', 'C', NULL, '["Extended Family Home", "Over 2,000 Sq Ft Of Accommodation", "Five Bedrooms, Four Bathrooms", "Spacious Double Reception Room", "Stylish Kitchen And Dining Space", "Excellent Transport Links Into Central London"]', 'A stunning five-bedroom period home, ideally positioned on Queenswood Road, a quiet residential street between Forest Hill and Sydenham. Offering over 2,000sqft. of beautifully proportioned accommodation, the property has been thoughtfully extended and enhanced by the current owners, including a loft extension which has created an additional double bedroom with an en-suite shower room. The result is a spacious and versatile family home, combining generous living space with stylish and well-considered interiors.
INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields, split) VALUES ('rm-93206253', 'rapidapi_uk_real_estate_rightmove', '93206253', 'https://www.rightmove.co.uk/properties/93206253', 700000, NULL, 4, 3, 'semi_detached', 'Hunsdon Road, Oxford', 'OX4 4JE', 51.728977, -1.229717, 'freehold', NULL, NULL, NULL, 'C', 'D', 'C', NULL, '["Three Storey Semi Detached Home", "Thoughtfully Re-Furbished", "Rear Extension & Loft Conversion", "Quiet Cul-de-Sac Location", "Open Plan Dining/Family Area", "French Doors opening onto Rear Garden", "Two Family Bathrooms", "Loft Room with En-suite & Juliette Balcony", "Garden Office/Studio", "Easy Access to Road, Recreation & Retail Facilities."]', 'A charming 3-storey, bay-fronted semi-detached home that’s undergone thoughtful refurbishment by the current owners, with rear extension and loft conversion. Ideally located for families in a quiet cul-de-sac in a sought-after neighbourhood with easy access to local amenities, the accommodation is arranged over three floors and balances 1930s period detail with the effortless flow of modern living.
INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields, split) VALUES ('rm-93247686', 'rapidapi_uk_real_estate_rightmove', '93247686', 'https://www.rightmove.co.uk/properties/93247686', 1150000, 'guide_price', 3, 3, 'flat', 'Furnace House, Waterfront', 'OX2 6GF', 51.761574, -1.269733, 'leasehold', 196, 4571.02, NULL, 'E', 'D', 'C', NULL, '["Prestigious City Address", "Spectacular and Sizeable Penthouse Apartment Served by Elevator", "Air Conditioning and Under Floor Heating", "Two Dual Aspect Private Balconies", "Inviting Entrance Hall with Cloak/Bathroom", "Stunning Open Plan Sitting Room with dining Area and Fully Fitted Kitchen", "Two Double Bedrooms with En Suite Shower Rooms", "Third Bedroom/Study", "Two Secure Underground Parking Spaces with Option for Electric Charging", "No Onward Chain"]', 'Enjoy a prestigious city address with this spectacular penthouse apartment on this exclusive development built around a large central piazza adjacent to the Oxford canal on the edge of fashionable and vibrant Jericho. The apartment is approached via a video entry phone and staircase or elevator to the fourth/top floor. There is an entrance lobby with front door to an inviting reception hall with built in cloaks cupboard and double doors opening into a light and spacious open plan sitting room with dining area and fully fitted kitchen with appliances. All of this enjoying an out look over the piazza and Oxford canal from a private balcony. There is a guest cloak/bathroom and two spacious double bedrooms with built in wardrobes and en suite shower rooms. There is also a third bedroom/study with private balcony. Under floor heating and air conditioning. Two secure underground parking spaces with option for electric charging points.
INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields, split) VALUES ('rm-93253092', 'rightmove', '93253092', 'https://www.rightmove.co.uk/properties/93253092', 700000, 'offers_over', 4, 2, 'detached', 'Brookdene Avenue, Watford, Oxhey Hall, WD19', 'WD19 4LG', 51.63799, -0.39612, 'freehold', NULL, NULL, NULL, NULL, 'C', 'A', NULL, '["Spacious 4 bedroom home in need of modernisation", "Bright reception room with excellent natural light", "Generous fitted kitchen with ample storage and workspace", "Four well-proportioned bedrooms arranged over two floors", "Family bathroom with scope to modernise", "Large private rear garden with mature planting", "Driveway parking and side access", "ought-after residential location with excellent family appeal"]', '*In need of modernisation* A spacious 4 bedroom family home offering versatile living space, a fitted kitchen, generous rear garden and excellent potential, set within the highly sought-after Oxhey Hall area.
INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields, split) VALUES ('rm-93281244', 'rightmove', '93281244', 'https://www.rightmove.co.uk/properties/93281244', 625000, NULL, 1, 1, 'flat', 'Cyntra Place, 201 Mare Street, Hackney, London, E8', 'E8 3QE', 51.540987, -0.055366, 'share_of_freehold', 974, 1566, NULL, 'D', 'D', 'C', NULL, '["Converted Victorian Factory", "Gated Mews Development Just Off Mare Street", "Share Of Freehold", "Exposed Brickwork And Crittall-Style Windows", "Expansive Open-Plan Kitchen, Living And Dining Space", "Offered With No Onward Chain"]', 'Rarely available to market is this beautifully desinged one-bedroom apartment, forming part of a converted Victorian factory within a gated mews development just off Mare Street. The property combines a wealth of original industrial character with a generous and versatile layout, while also benefiting from a share of freehold.
