INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields, split) VALUES ('rm-93370545', 'rightmove', '93370545', 'https://www.rightmove.co.uk/properties/93370545', 800000, 'guide_price', 3, 2, 'flat', 'Josephine Avenue, London, SW2', 'SW2 2LA', 51.45478, -0.116741, 'leasehold', 120, 1313.64, 400, 'D', 'D', 'D', 'first', '["Nearly 1100 sq ft of beautifully designed internal space", "3 double bedrooms over the ground and first floors of a Victorian conversion", "Architecturally exceptional open-tread staircase with glass balustrades and geometric lighting", "2 bath/shower rooms including 1 ensuite", "Private rear garden with SW aspect", "Off-street parking as part of access to a large additional space, though not demised", "Strikingly stylish kitchen with marble worktops and breakfast bar", "Superb ceiling heights and large bay windows for great natural light", "Offered with 119 years lease remaining, and no onward chain", "4 minutes'' walk to Brockwell Park"]', 'One of the most stylish Victorian conversions you’re likely to see. This ground- and first- floor flat offers three double bedrooms, two bath/shower rooms (including one ensuite), and a private south-west facing garden. The flat also has use of a large additional garden / off-street parking area, albeit not demised.
INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields, split) VALUES ('rm-93377520', 'rapidapi_uk_real_estate_rightmove', '93377520', 'https://www.rightmove.co.uk/properties/93377520', 290000, 'offers_in_region', 2, 1, 'end_of_terrace', 'Ebenezer Terrace, Tabors Hill, Great Baddow, Chelmsford, CM2', 'CM2 7BL', 51.71866, 0.499, 'freehold', NULL, NULL, NULL, 'C', 'C', 'B', 'ground', '["No onward chain", "Two bedroom end of terrace house", "Requiring modernisation", "Located in a conservation area", "Good size rear garden", "Ground floor shower room"]', 'Located in a Conservation area in the popular village of Great Baddow is this two-bedroom end of terrace home requiring modernisation and being offered with no onward chain. This property offers great a great opportunity for first time buyers to get on the ladder and make their own. Internally the property consists of an open plan lounge / diner which leads through to the extended open plan kitchen / breakfast area with access leading to the rear garden. The shower room is also located on the ground floor. The first floor offers the two bedrooms. Externally this home has a good size rear garden. Further benefits include gas central heating and storage throughout. To appreciate this opportunity to its full potential, we strongly recommend an early internal inspection.
