INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields, split) VALUES ('rm-93622338', 'rapidapi_uk_real_estate_rightmove', '93622338', 'https://www.rightmove.co.uk/properties/93622338', 1200000, 'guide_price', 3, 2, 'detached', 'Red Copse End, Red Copse Lane, Boars Hill, OX1 5ER', 'OX1 5ER', 51.71917, -1.279982, 'freehold', NULL, NULL, NULL, 'F', 'C', 'C', NULL, '["Inviting entrance hall provides access to a cloakroom and seperate shower room", "Impressive dual-aspect kitchen/family room fitted with an excellent range of floor and wall mounted units complemented by a separate boot room/utility room", "Separate study, spacious dual aspect dining room and living room featuring stylish bespoke wall furniture", "Superb garden room, with a vaulted ceiling and providing panoramic views over the beautiful gardens", "Two double bedrooms with fitted wardrobe cupboards and third bedroom (currently used as a study) all served by a re-fitted shower room", "The grounds extend to just over one acre and are approached via electronically powered gates, opening onto an extensive driveway providing parking for several vehicles leading to a detached garage", "A large south-facing terraced area and courtyard patio provide delightful sunny seating areas leading to lawn and mature woodland including maple and oak trees", "Excellent potential exists to significantly enlarge the property, creating a substantial family residence, which has proven to be a popular option among neighbouring properties"]', 'Highly individual detached family home, complemented by beautiful gardens extending to approximately one acre, including established woodland, situated at the end of this private and highly regarded residential setting in Boars Hill offering the perfect balance of tranquil semi-rural living combined with convenient access to Oxford city centre and Abingdon.
INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields, split) VALUES ('rm-93636978', 'rapidapi_uk_real_estate_rightmove', '93636978', 'https://www.rightmove.co.uk/properties/93636978', 300000, 'offers_over', 3, 1, 'semi_detached', 'Routh Road, Headington, Oxford', 'OX3 8DA', 51.767147, -1.190896, 'freehold', NULL, NULL, NULL, 'B', 'C', 'B', 'ground', '["- No onward chain", "- Generous rear garden", "- Well proportioned bedrooms", "- Close to bus links for Oxford"]', 'Offered with no onward chain, this three bedroom home is tucked away in a quiet cul-de-sac and benefits from a particularly generous rear garden, while offering convenient access to Oxford and excellent transport connections.
INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields, split) VALUES ('rm-93639996', 'rightmove', '93639996', 'https://www.rightmove.co.uk/properties/93639996', 1150000, 'offers_over', 4, 3, 'detached', 'Old Barn Close, Emmer Green, Reading', 'RG4 8QY', 51.484804, -0.973554, 'freehold', NULL, NULL, NULL, 'G', 'B', 'B', NULL, '["Four bedroomed detached house", "Immaculate decorative order throughout", "Large living/dining area", "Kitchen with separate utility room", "Vast garden", "Parquet flooring throughout living areas", "Quiet cul de sac", "Onward chain is closed!"]', 'Bridges are delighted to bring to the market this four bedroomed, detached house situated in a generous corner plot in a quiet cul de sac in the heart of Emmer Green. Set behind electric gates the front drive is paved and provides parking for multiple cars. Accessed via an enclosed porch the house benefits from parquet flooring running throughout the downstairs living areas and is flooded with light due to glass panelled doors and partitions. Presented in immaculate decorative order throughout the property has a vast living/dining area which leads to an orangery with underfloor heating, two sets of French Doors, to garden, and a vast, domed roof lantern. The kitchen benefits from a range of floor and eye level units and has space for a table. There is a separate utility/laundry room, study, with fitted furniture and cloakroom. Upstairs are four double bedrooms, the main with a wall of built in wardrobes. There are two family bathrooms one with bath and hand shower and the other with separate shower and jacuzzi style bath. The garden is large with a patio area, established planting and generous lawn. There is a double garage with electric door and two brick storage areas. The onward chain is closed and an early viewing recommended by the vendors` sole agent!
