INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields, split) VALUES ('rm-93912573', 'rapidapi_uk_real_estate_rightmove', '93912573', 'https://www.rightmove.co.uk/properties/93912573', 1125000, 'guide_price', 4, 3, 'house', 'New Park Street, Cambridge, Cambridgeshire', 'CB5 8AT', 52.210342, 0.118812, 'freehold', NULL, NULL, NULL, 'G', 'B', 'A', NULL, '["Open plan Kitchen/Dining Room with wooden floors and door to front aspect", "Fitted Kitchen area with wall and base units and integrated appliances and separate Utility Room", "Dual aspect Sitting Room with wooden floors and stairs down to Garden", "Top Floor Principal Bedroom with fitted wardrobes, en suite Shower Room and door to Balcony", "3 further Bedrooms arranged and 2 Bath/Shower Rooms ( 1 en suite)", "Further Balcony leading from Bedroom 2", "Courtyard Garden and Separate Garage en bloc", "NO ONWARD CHAIN"]', 'A desirable, four bedroom townhouse benefiting from a garage and easy access to Cambridge city centre, the River Cam and Jesus Green.
INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields, split) VALUES ('rm-93935772', 'rapidapi_uk_real_estate_rightmove', '93935772', 'https://www.rightmove.co.uk/properties/93935772', 1200000, 'offers_over', 4, 2, 'flat', '28 Fairholme Road, London, W14 9', 'W14 9JX', 51.38541, -0.110056, 'leasehold', 139, NULL, NULL, NULL, 'D', 'B', NULL, '["Period charm, including high ceilings and large bay windows.", "139 years lease remaining.", "Unmodernised, offering enormous scope for refurbishment and personalisation.", "Outside space (balcony & roof terrace).", "Ideally positioned within easy walking distance of Barons Court Underground Station and West Kensington Underground Stations."]', 'Occupying in excess of 1,600 sq ft of internal accommodation, this substantial four-bedroom maisonette forms part of an elegant stucco-fronted Victorian terrace and presents a rare opportunity to acquire a home of impressive scale and character in one of West London''s most desirable residential locations.The property boasts a wealth of period charm, including high ceilings, large bay windows and beautifully proportioned rooms throughout. The magnificent reception room provides an outstanding entertaining space, flooded with natural light and enjoying an attractive sense of grandeur, while the spacious kitchen/breakfast room offers ample space for family living and future enhancement.The accommodation comprises four generously sized bedrooms, including a principal bedroom with en-suite bathroom, together with a separate family bathroom. Two private balconies further enhance the feeling of space and provide pleasant outlooks.A particular highlight is the exceptional south-facing roof terrace, enjoying far-reaching views across the London skyline. Rarely found in properties of this type, this outstanding outdoor space provides the perfect setting for entertaining, al fresco dining or simply enjoying the spectacular aspect.While the property would benefit from updating, it offers enormous scope for refurbishment and personalisation, allowing an incoming purchaser to create a truly exceptional home tailored to their own taste and requirements.Ideally positioned within easy walking distance of Barons Court Underground Station and West Kensington Underground Station, the property also enjoys convenient access to Central London, the A4/M4 corridor and Heathrow Airport.Combining generous proportions, period elegance, remarkable outdoor space and significant potential, this is an increasingly rare opportunity to create a landmark home in a prime West London location.
INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields, split) VALUES ('rm-93944799', 'rightmove', '93944799', 'https://www.rightmove.co.uk/properties/93944799', 800000, NULL, 3, 1, 'maisonette', 'Tremlett Grove, Archway, London', 'N19 5LA', 51.561411, -0.137426, 'share_of_freehold', NULL, NULL, NULL, NULL, 'D', 'C', '1st', '["Three Bedrooms", "Spacious Triple Aspect Reception Room", "Modern Fitted & Equipped Kitchen", "Stylish Bathroom", "South Facing Roof Terrace", "Partially Air Conditioned", "Lotos of Useful Built-in Storage", "Moments from Excellent Amenities"]', 'This delightful property has a large triple aspect on the top floor which leads to a modern fitted and equipped kitchen. There are three well-proportioned bedrooms and a stylish bathroom on the second floor. Of particular interest is the ''suntrap'' roof terrace which enjoys a light open aspect to the rear overlooking surrounding gardens. The property is close to an excellent choice of amenities at both Tufnell Park and Archway and moments away from Dartmouth Park.', 'Buchanan Rae Wilson, Dartmouth Park', '2026-10-05T17:19:35Z', '2026-10-23T22:52:28Z', '[]', 'eval');
