INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields, split) VALUES ('rm-94014951', 'rapidapi_uk_real_estate_rightmove', '94014951', 'https://www.rightmove.co.uk/properties/94014951', 1200000, NULL, 4, 2, 'terraced', 'Chevening Road, Greenwich, SE10', 'SE10 0LB', 51.485363, 0.013178, 'freehold', NULL, NULL, NULL, 'E', 'C', 'B', NULL, '["Four-bedroom Victorian family home", "Extended accommodation over three floors", "Approx. 1,432 sq ft (133.03 sq m)", "Beautifully presented throughout", "Stunning contemporary kitchen", "Downstairs W.C.", "Private 29ft rear garden", "Backing directly onto East Greenwich Pleasaunce", "Halstow Primary School catchment", "Sought-after East Greenwich location"]', 'Occupying a sought-after position in the heart of East Greenwich and backing directly onto the beautiful East Greenwich Pleasaunce, this exceptional four-bedroom Victorian family home offers approximately 1,432 ft 2 of beautifully presented accommodation arranged over three floors. Retaining a wealth of period charm, the property combines elegant original features with high-quality contemporary finishes, creating a perfect home for modern family living. The ground floor comprises a stunning through reception and dining room with feature fireplace, bespoke cabinetry and herringbone flooring, while to the rear a stylish extended kitchen offers excellent storage, generous worktop space and direct access to the private rear garden. A downstairs W.C. completes the ground floor.
