INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields, split) VALUES ('rm-94076055', 'rightmove', '94076055', 'https://www.rightmove.co.uk/properties/94076055', 800000, NULL, 3, 1, 'maisonette', 'Median Road, Hackney, London, E5', 'E5 0PN', 51.552976, -0.049221, 'share_of_freehold', NULL, NULL, NULL, 'C', 'B', 'A', NULL, '["Almost 1,000 sq ft of beautifully proportioned accommodation", "Three well-proportioned bedrooms", "Set across the upper floors of a handsome Victorian residence", "Wealth of original period features", "Delightful private balcony", "Perfectly positioned between Chatsworth Road & Lower Clapton Road"]', 'Set on Median Road, one of Clapton’s most attractive and leafy residential streets, this impressive three-bedroom Victorian duplex apartment occupies the upper floors of a handsome period residence and offers almost 1,000 sq. ft of beautifully proportioned accommodation. Filled with character and charm, the property retains a wealth of original features, including beautiful timber flooring, high ceilings and elegant period detailing, giving the home a wonderfully timeless feel.
INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields, split) VALUES ('rm-94092237', 'rapidapi_uk_real_estate_rightmove', '94092237', 'https://www.rightmove.co.uk/properties/94092237', 700000, NULL, 4, 3, 'semi_detached', 'The Drive, Coulsdon, CR5', 'CR5 2BL', 51.326687, -0.133088, 'freehold', NULL, NULL, NULL, 'F', 'C', 'C', 'first', '["Stunning New Build", "No Onward Chain", "Four Double Bedrooms", "Three Bathrooms", "Driveway (EV Charger)", "Utility Room", "Fitted Wardrobes In Every Bedroom", "Air Source Heat Pump System"]', 'James Bailey is proud to present this incredible four double bedroom semi detached new build home with No Onward Chain. Recently built and therefore offered in exceptional condition throughout the property has a very spacious front room as well as incredible fully fitted kitchen and open reception room to the rear. There is a utility room and downstairs WC with bi-fold doors leading out to the patio and private garden. On the first floor are two double bedrooms complete with bespoke fitted wardrobes and a family bathroom. There is a third double bedroom also with bespoke cabinets and en-suite bathroom. The top floor contains the largest bedroom with bespoke fitted wardrobes and an en-suite shower room. Further benefits include underfloor heating on the ground floor, an air source heat pump system for energy efficiency and off-street parking for a car with EV charger.
INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields, split) VALUES ('rm-94104951', 'rapidapi_uk_real_estate_rightmove', '94104951', 'https://www.rightmove.co.uk/properties/94104951', 1200000, 'guide_price', 3, 2, 'flat', 'South Park, Sevenoaks, Kent, TN13', 'TN13 1EW', 51.271133, 0.187234, 'leasehold', NULL, 1700.0, NULL, 'E', 'D', 'C', NULL, '["2030 sq ft Duplex apartment", "3 Double bedrooms", "High ceilings and period features", "Private garden and balcony", "Parking for 2 cars", "Beautifully presented and updated", "Short walk to the town centre and station"]', 'An elegant 2,030 sq ft duplex apartment in this Victorian building with private garden, balcony and parking, set off a private road between the town and railway station
INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields, split) VALUES ('rm-94112421', 'rapidapi_uk_real_estate_rightmove', '94112421', 'https://www.rightmove.co.uk/properties/94112421', 1150000, 'offers_over', 5, 3, 'detached', 'Arundel Drive East, Saltdean, BN2', 'BN2 8SL', 50.804703, -0.03929, 'freehold', NULL, NULL, NULL, 'E', 'D', 'B', NULL, '["Five Bedrooms", "Three Bathrooms", "Stunning Sea Views", "Prime Saltdean Road & Location", "Vaulted Living Space", "Garden Office", "Garage & Driveway", "Immaculately Presented", "Two Balconies", "No Chain"]', 'Contemporary coastal living with breath-taking sea views
INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields, split) VALUES ('rm-94126035', 'rapidapi_uk_real_estate_rightmove', '94126035', 'https://www.rightmove.co.uk/properties/94126035', 1150000, 'guide_price', 3, 2, 'detached', 'Kings Road, Kingston Upon Thames', 'KT2 5JL', 51.419743, -0.287841, 'freehold', NULL, NULL, NULL, 'E', 'D', 'C', 'ground', '["Detached Victorian Family Home", "Three Bedrooms", "Family Bathroom and Downstairs WC/Shower", "South Facing rear Garden", "Well Presented Internally", "Underfloor heating throughout", "Moments From Richmond Park", "Open-Plan Kitchen/Diner", "EPC Rating - D", "Council Tax band - E"]', 'Situated on the top section of Kings Road, moments from Richmond Park in Kingston upon Thames, this delightful Victorian detached family home offers a perfect blend of period elegance and modern comfort. Spanning an impressive 1,463 square feet, the property boasts a stunning front reception room with wood burning stove and an additional reception room to the back opening onto a modern open-plan kitchen/diner. From there, bifold doors lead onto a south-facing rear garden, ideal for both entertaining guests and enjoying family time. The home features underfloor heating throughout and has three well-appointed bedrooms, providing ample space for a growing family or guests. The family bathroom is thoughtfully designed, while an additional shower and WC on the ground floor adds convenience for busy mornings or when hosting visitors. In addition, there is a loft area which is currently used as a 4th bedroom but is not an official loft conversion due to certain restrictions including head height. Internally, the property is well presented, showcasing the character and charm typical of Victorian architecture, yet it has been maintained to meet contemporary living standards. One of the standout features of this home is its proximity to the stunning Richmond Park, offering a perfect escape for leisurely walks, picnics, or outdoor activities. This property is not just a house; it is a warm and inviting family home, ready to create lasting memories. With its prime location and spacious layout, it is an opportunity not to be missed.
