INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields, split) VALUES ('rm-94269678', 'rightmove', '94269678', 'https://www.rightmove.co.uk/properties/94269678', 1175000, 'offers_over', 5, 2, 'end_of_terrace', 'Highview Road, Ealing, W13', 'W13 0HN', 51.519024, -0.325119, 'freehold', NULL, NULL, NULL, 'F', 'B', 'B', 'first', '["Elegant Period Family Home", "Two Reception Rooms", "WC/Cloakroom", "Utility Room", "Five Bedrooms", "Two Bathrooms", "Split Level Garden/Studio Office", "Half Mile To Elizabeth Line"]', 'A superb end-of-terrace family home which has been recently enhanced and updated by the current owners to an excellent standard, whilst retaining much of its early 20th-century character and charm. The ground floor features a comfortable front reception room leading through to a spacious open-plan kitchen and dining area. The recently updated kitchen offers ample fitted cabinetry and integrated appliances, with matching units continuing into the adjoining utility area. A convenient guest WC completes the ground floor. On the first floor are two generous double bedrooms, a single bedroom, currently arranged as a dressing room, and a family bathroom. The top floor offers two further bedrooms, including a well-proportioned double and a good-sized single, together with a separate bathroom, providing flexible accommodation for a growing family.
