INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields, split) VALUES ('rm-94467663', 'rightmove', '94467663', 'https://www.rightmove.co.uk/properties/94467663', 1050000, NULL, 3, 1, 'end_of_terrace', 'Brunner Road, Ealing', 'W5 1BA', 51.527137, -0.306455, 'freehold', NULL, NULL, NULL, 'F', 'B', 'A', NULL, '["Beautifully Appointed End of Terrace Period House", "Three Bedrooms", "Brentham Garden Suburb Conservation Area", "High Ceilings and Large Sash Windows", "Spacious Through Reception/Dining Room", "Lovely Front and Rear Gardens", "Close to Pitshanger Lanes Amenities", "Easy Access for Elizabeth Line Stations", "Montpelier School Catchment Area", "984 sq ft (105.1 sq. m)"]', 'A beautifully appointed three-bedroom end-of-terrace Brentham House, showcasing stylish interiors complemented by charming period features. This handsome home, with its striking bay elevations, was built in the early 1900s and is ideally situated within the highly sought-after Brentham Garden Suburb Conservation Area. The ground floor offers a spacious and versatile through reception room, providing excellent living and dining space with direct access to the rear garden. A well-designed, fully integrated kitchen also enjoys direct access to the garden. Upstairs, the first floor provides three well-proportioned bedrooms and a stunning family bathroom. The property is flooded with natural light throughout, enhanced by its desirable east/west aspect and large sash windows. To the front, the property enjoys a lovely garden, adding to its attractive kerb appeal. To the rear, the attractive garden features a generous patio area, artificial lawn designed for low-maintenance living, and the added benefit of useful side access. As the vendors'' sole agent, we strongly advise an early inspection of this exceptional home.
