INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields, split) VALUES ('rm-94592364', 'rightmove', '94592364', 'https://www.rightmove.co.uk/properties/94592364', 450000, 'fixed_price', 2, 1, 'flat', 'Harriet Court, 29 Pomeroy Street, London, SE14', 'SE14 5BW', 51.476239, -0.052438, 'leasehold', 115, 1625.76, 250, 'C', 'C', 'A', 'first', '["First Floor (building has a lift)", "Approx. 809 Sqft Gross Internal Area", "Spacious, Open-Plan Kitchen/Reception", "Two Good-Sized Double Bedrooms", "Stylish Bathroom", "Very Good Energy Efficiency Rating", "Large Balcony", "Short Walk to Queens Road Peckham Station"]', 'A spacious apartment on the first floor of this modern development. The property has a twenty-five foot reception room with open-plan kitchen area featuring sleek, white units and integrated appliances. There is a main bedroom with fitted wardrobe plus a very similar-sized second double bedroom, a stylish bathroom and a large hallway storage cupboard. A large balcony can be accessed from either the living room or the main bedroom. Harriet Court was built with well insulated walls and floor, high performance glazing and gas central heating systems resulting in a very good energy-efficiency rating. Queens Road Peckham Station, for London Overground trains plus Southern services between East Croydon/Beckenham Junction and London Bridge, is just a short walk away.
