INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields, split) VALUES ('rm-94604223', 'rightmove', '94604223', 'https://www.rightmove.co.uk/properties/94604223', 475000, 'guide_price', 4, 2, 'terraced', 'Hall Gardens, Colney Heath, AL4', 'AL4 0QF', 51.739259, -0.250283, 'freehold', NULL, NULL, NULL, 'D', 'D', 'D', 'ground', '["Three Bedrooms", "Two Reception Rooms", "Ground Floor Bedroom + En-Suite", "Gas Central Heating", "Open Aspect to Rear", "Off Street Parking Space", "No Upper Chain"]', 'This spacious and well-proportioned FOUR BEDROOM family home in Hall Gardens, Colney Heath, offers approximately 1,208 sq. ft. of versatile accommodation arranged over two floors, making it an ideal choice for growing families or those looking for additional space. The property benefits from OFF STREET PARKING to the front, a generous private rear garden and a useful detached garden store.
INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields, split) VALUES ('rm-94604541', 'rightmove', '94604541', 'https://www.rightmove.co.uk/properties/94604541', 575000, 'guide_price', 2, 1, 'terraced', 'Sopwell Lane, St Albans, AL1', 'AL1 1RN', 51.748047, -0.337083, 'freehold', NULL, NULL, NULL, 'E', 'B', 'A', NULL, '["Charming Period Cottage Arranged Over Two Floors", "Private Rear Garden", "Two Double Bedrooms", "No Onward Chain", "Open-Plan Living/Dining Room Extending 24ft in Length", "Close to St Albans City Centre & Mainline Station"]', 'Nestled within the quiet, historic streets of the Sopwell Lane Neighbourhood, this lovely home offers a slice of idyllic St Albans lifestyle, just a short stroll from the town centre, 11th Century Cathedral and Verulamium parklands.
INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields, split) VALUES ('rm-94606008', 'rightmove', '94606008', 'https://www.rightmove.co.uk/properties/94606008', 294500, 'guide_price', 1, 1, 'flat', 'Holywell Hill, St Albans, AL1', 'AL1 2PS', 51.74453, -0.34302, 'leasehold', 999, 1171.42, NULL, NULL, 'D', 'C', NULL, '["One Bedroom Apartment", "Close to Station", "SHOW HOME AVAILABLE TO VIEW!"]', 'A superb opportunity to purchase a brand-new apartment within an exciting development of 63 contemporary homes in the heart of St Albans.
INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields, split) VALUES ('rm-94606086', 'rightmove', '94606086', 'https://www.rightmove.co.uk/properties/94606086', 1150000, NULL, 5, 1, 'semi_detached', 'Drayton Green, West Ealing, Ealing, W13', 'W13 0JF', 51.516199, -0.325771, 'freehold', NULL, NULL, NULL, NULL, 'D', 'C', NULL, '["Five Bedroom Victorian Family Home", "Three Spacious Reception Rooms", "West facing garden overlooking Drayton Green", "Light-filled Conservatory with utility space", "Private Rear Garden with Detached Home Office", "Versatile second Floor with bedroom, photography darkroom and plenty of scope to extend"]', 'A wonderful balance of traditional features and everyday practicality makes this an inviting home, while the secluded garden and detached garden office offer additional space for relaxation, creativity and home working. A truly individual property with plenty to offer. The ground floor features a bay-fronted reception room, separate dining room, kitchen and second reception room opening onto a conservatory. The first floor offers four bedrooms and a family bathroom, while the second floor provides a fifth bedroom and a dedicated photography darkroom, offering excellent flexibility. Situated on Drayton Green, the property is conveniently positioned for Drayton Green Primary School, St John’s Primary School and Drayton Manor High School.
INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields, split) VALUES ('rm-94606242', 'rapidapi_uk_real_estate_rightmove', '94606242', 'https://www.rightmove.co.uk/properties/94606242', 985000, NULL, 5, 1, 'house', 'Roxwell Road, Chelmsford, CM1', 'CM1 2NE', 51.741028, 0.443951, 'freehold', NULL, NULL, NULL, NULL, 'B', 'A', NULL, '["Spacious open-plan design with sliding doors to rear garden", "British-made kitchens, AEG appliances, Crittall-style internal doors, and underfloor heating with smart controls", "Less than 10 minutes to Chelmsford station (33 mins to London Liverpool Street), with easy access to A12, M11, and Elizabeth Line", "Versatile layouts including a top-floor principal suite with dressing room and ensuite", "Limited collection of just six luxury detached homes", "Air source heat pump, EV charging point, and fibre broadband", "Walking distance to top grammar and primary schools; close to leading private schools and nurseries", "Secure parking with remote-controlled garage doors and extra external storage"]', '*Incentives Now Avaliable - Booking Your Viewing Today* Welcome to Roxwell Row. A private road of just six contemporary houses, set on the edge of the city with easy access to open countryside and less than a 10-minute drive to the high street and railway station. Each house at Roxwell Row is designed for family life and finished to a superb standard. The heart of the home is a spacious open-plan kitchen, living, and dining area with large sliding doors opening onto a private rear garden—perfect for entertaining or relaxing. There’s a separate lounge, handy utility room, cloakroom, and a welcoming entrance hall with a feature curved staircase. Upstairs, the first floor offers four generous bedrooms, one with an ensuite, plus a flexible fifth bedroom or study—ideal for home working. The top floor is dedicated to a luxurious main bedroom suite, complete with a dressing room and stylish ensuite bathroom. All homes are finished with British-made kitchens, integrated Bosch appliances, composite stone worktops and Crittall-style doors. Features include underfloor heating with smart controls, an energy-efficient air source heat pump, EV charging point, high-speed fibre broadband wiring, and a double garage with remote doors. Roxwell Row is set back from the road in a peaceful, green setting yet minutes from Chelmsford city centre. Outstanding local schools—such as Chelmsford County High for Girls and KEGS grammar—are close by, along with excellent state and private schools and nurseries. The station offers direct trains to London in just 33 minutes. The A12, M11, and new Elizabeth Line connections are all easily reached.
INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields, split) VALUES ('rm-94606443', 'rightmove', '94606443', 'https://www.rightmove.co.uk/properties/94606443', 305500, 'guide_price', 1, 1, 'flat', 'Holywell Hill, St Albans, AL1', 'AL1 2PS', 51.74453, -0.34302, 'leasehold', 999, 1171.42, NULL, NULL, 'D', 'B', 'second', '["One Bedroom Apartment", "Close to Station", "SHOW HOME AVAILABLE TO VIEW!"]', 'A superb opportunity to purchase a brand-new apartment within an exciting development of 63 contemporary homes in the heart of St Albans.
