INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields, split) VALUES ('rm-94680357', 'rightmove', '94680357', 'https://www.rightmove.co.uk/properties/94680357', 390000, NULL, 1, 1, 'flat', 'Embassy House, West Hampstead, NW6', 'NW6 2NB', 51.54436, -0.191946, 'leasehold', 132, NULL, NULL, 'C', 'C', 'C', 'second', '["Lift access", "Renovated by the owner", "Chevron flooring throughout", "Vast storage", "Modern kitchen and bathroom", "Long lease"]', 'A beautifully presented one-bedroom apartment for sale in the sought-after Embassy House, West Hampstead, NW6. Renovated by the current owner, the property offers stylish, modern interiors and is ready for its next owner to move straight in, with improvements including a modern fitted kitchen, contemporary bathroom, new flooring, windows and boiler.
INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields, split) VALUES ('rm-94680747', 'rightmove', '94680747', 'https://www.rightmove.co.uk/properties/94680747', 800000, 'offers_over', 1, 1, 'flat', 'One Casson Square, Southwark, London', 'SE1 7GT', 51.504252, -0.115335, 'leasehold', 988, 8887.0, 600.0, 'F', 'C', 'B', 'fourth', '["Spacious and bright one-bedroom flat", "Set on the fourth floor", "Fabulous dual aspect views", "Long lease", "Impressive and private residents'' facilities", "Excellent transportation links", "Tenancy in situ"]', 'GHE is delighted to present this well-maintained one-bedroom apartment on the fourth floor of the highly sought-after Casson Square development at Southbank Place, Waterloo.
INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields, split) VALUES ('rm-94680756', 'rightmove', '94680756', 'https://www.rightmove.co.uk/properties/94680756', 400000, NULL, 2, 1, 'flat', 'Eardley Road, London, SW16', 'SW16 6BJ', 51.421259, -0.139327, 'leasehold', 94, NULL, 150, 'C', 'C', 'B', 'ground', '["0.3 Miles from Streatham Common Train Station", "0.6 Miles from Streatham Train Station", "Own Front Door", "Private Courtyard Garden", "Enclosed Porch", "Double Glazed Sash Windows", "Under Floor Heating Throughout", "Open Plan Living Space", "Two Double Bedrooms", "Wandsworth Council"]', 'A truly unique and characterful two double bedroom ground floor maisonette, offering generous living space, a private courtyard garden and a wealth of bespoke features throughout.
INSERT INTO listings (id, source, source_id, url, price_gbp, price_qualifier, bedrooms, bathrooms, property_type, address, postcode, lat, lon, tenure, lease_years_remaining, service_charge_gbp_pa, ground_rent_gbp_pa, council_tax_band, epc_current, epc_potential, floor_level, key_features, description, agent_name, listed_date, fetched_at, parsed_fields, split) VALUES ('rm-94680831', 'rightmove', '94680831', 'https://www.rightmove.co.uk/properties/94680831', 500000, 'guide_price', 1, 1, 'flat', 'Cube Building, Wenlock Road, London, N1', 'N1 7GU', 51.531644, -0.094395, 'leasehold', 989, NULL, 450, NULL, 'D', 'B', NULL, '["Close to public transport", "Concierge", "Shops and amenities nearby", "Video Entry", "Private Balcony", "Highly Desired Location", "Fantastic Views"]', 'This bright and spacious one-bedroom apartment is located in the award-winning Cube Building, located on the corner, the property benefits from a large wrap private terrace. The property has river views and is within close proximity to public transport, shops, restaurants, cafes and local amenities.
